#include <iostream>
#include <cstring>
#include <queue>
#include <vector>
#include <cctype>
#include <algorithm>
#include <climits>
using namespace std;

using i64 = long long;
const int INF = 0x3f3f3f3f;
const int MAXN = 210;

struct FlowEdge {
    int to, rev;
    int cap;
    FlowEdge(int t, int c, int r) : to(t), cap(c), rev(r) {}
};

vector<FlowEdge> g[MAXN];
int lvl[MAXN], ptr[MAXN];

void addEdge(int u, int v, int c) {
    g[u].emplace_back(v, c, g[v].size());
    g[v].emplace_back(u, 0, g[u].size() - 1);
}

void bfs(int s) {
    memset(lvl, -1, sizeof(lvl));
    queue<int> q;
    lvl[s] = 0;
    q.push(s);
    while (!q.empty()) {
        int u = q.front(); q.pop();
        for (const auto& e : g[u]) {
            if (e.cap > 0 && lvl[e.to] < 0) {
                lvl[e.to] = lvl[u] + 1;
                q.push(e.to);
            }
        }
    }
}

int dfs(int u, int t, int f) {
    if (u == t) return f;
    for (int& i = ptr[u]; i < (int)g[u].size(); ++i) {
        FlowEdge& e = g[u][i];
        if (e.cap > 0 && lvl[u] < lvl[e.to]) {
            int pushed = dfs(e.to, t, min(f, e.cap));
            if (pushed > 0) {
                e.cap -= pushed;
                g[e.to][e.rev].cap += pushed;
                return pushed;
            }
        }
    }
    return 0;
}

int dinic(int s, int t) {
    int flow = 0;
    while (true) {
        bfs(s);
        if (lvl[t] < 0) return flow;
        memset(ptr, 0, sizeof(ptr));
        int pushed;
        while ((pushed = dfs(s, t, INF)) > 0) {
            flow += pushed;
        }
    }
}

const int dx[4] = {0, 0, 1, -1};
const int dy[4] = {1, -1, 0, 0};

int N, T, src, dst;
int cap[15][15], sci[15][15], grid[65][15][15];
bool seen[15][15];
bool ok[65][15][15][15][15];

int idx(int x, int y, int k) {
    return (x-1)*N + y + k*N*N;
}

void propagate(int sx, int sy, int x, int y, int step) {
    seen[x][y] = true;
    ok[step][sx][sy][x][y] = true;
    if (step >= T || grid[step][x][y]) return;
    for (int d = 0; d < 4; ++d) {
        int nx = x + dx[d], ny = y + dy[d];
        if (nx < 1 || ny < 1 || nx > N || ny > N) continue;
        if (seen[nx][ny] || grid[step][nx][ny]) continue;
        propagate(sx, sy, nx, ny, step + 1);
    }
}

void setup() {
    for (int t = 1; t <= T; ++t) {
        for (int x = 1; x <= N; ++x) {
            for (int y = 1; y <= N; ++y) {
                if (grid[t-1][x][y]) {
                    grid[t][x][y] = grid[t-1][x][y];
                } else {
                    for (int d = 0; d < 4; ++d) {
                        int nx = x + dx[d], ny = y + dy[d];
                        if (nx < 1 || ny < 1 || nx > N || ny > N) continue;
                        if (grid[t-1][nx][ny] == 2) {
                            grid[t][x][y] = 2;
                            break;
                        }
                    }
                }
            }
        }
    }
    for (int i = 1; i <= N; ++i) {
        for (int j = 1; j <= N; ++j) {
            if (sci[i][j]) {
                memset(seen, 0, sizeof(seen));
                propagate(i, j, i, j, 0);
            }
        }
    }
    for (int t = 1; t <= T; ++t) {
        for (int x = 1; x <= N; ++x) {
            for (int y = 1; y <= N; ++y) {
                for (int xx = 1; xx <= N; ++xx) {
                    for (int yy = 1; yy <= N; ++yy) {
                        ok[t][x][y][xx][yy] |= ok[t-1][x][y][xx][yy];
                    }
                }
            }
        }
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> N >> T;
    for (int i = 1; i <= N; ++i) {
        string s;
        cin >> s;
        for (int j = 1; j <= N; ++j) {
            char c = s[j-1];
            if (isdigit(c)) sci[i][j] = c - '0';
            else if (c == 'Y') grid[0][i][j] = 1;
            else if (c == 'Z') grid[0][i][j] = 2;
        }
    }
    for (int i = 1; i <= N; ++i) {
        string s;
        cin >> s;
        for (int j = 1; j <= N; ++j) {
            char c = s[j-1];
            if (isdigit(c)) cap[i][j] = c - '0';
        }
    }
    src = N*N*2;
    dst = src - 1;
    setup();
    for (int i = 1; i <= N; ++i) {
        for (int j = 1; j <= N; ++j) {
            if (sci[i][j]) addEdge(src, idx(i,j,0), sci[i][j]);
            if (cap[i][j]) addEdge(idx(i,j,1), dst, cap[i][j]);
        }
    }
    for (int x = 1; x <= N; ++x) {
        for (int y = 1; y <= N; ++y) {
            for (int xx = 1; xx <= N; ++xx) {
                for (int yy = 1; yy <= N; ++yy) {
                    if (sci[x][y] && cap[xx][yy] && ok[T][x][y][xx][yy]) {
                        addEdge(idx(x,y,0), idx(xx,yy,1), INF);
                    }
                }
            }
        }
    }
    cout << dinic(src, dst) << '\n';
    return 0;
}
